{% extends "templates/print/ph_basis.html" %}
{% block titel %}Lieferschein {{ doc.name }}{% endblock %}
{% block kopfrechts %}Lieferschein <b>{{ doc.name }}</b><br>Datum {{ ph_datum(doc.datum) }}<br>{% if doc.bestellung %}Bestellung {{ doc.bestellung }}<br>{% endif %}{% if doc.auftrag %}Auftrag {{ doc.auftrag }}<br>{% endif %}Lieferart {{ _(doc.lieferart) }}{% endblock %}
{% block inhalt %}
<h1>Lieferschein{% if doc.teillieferung %} (Teillieferung){% endif %}</h1>
<div class="ph-feld"><b>Lieferadresse</b> {{ doc.liefer_firma or "" }}{% if doc.liefer_firma %}<br>{% endif %}{{ doc.liefer_name or doc.kunde_name or "" }}<br>{{ doc.liefer_strasse or "" }} {{ doc.liefer_hausnr or "" }}{% if doc.liefer_zusatz %}, {{ doc.liefer_zusatz }}{% endif %}<br>{{ doc.liefer_plz or "" }} {{ doc.liefer_ort or "" }}{% if doc.liefer_land and doc.liefer_land != "AT" %}, {{ doc.liefer_land }}{% endif %}</div>
{% if doc.wunschtermin %}<div class="ph-feld"><b>Wunschtermin</b> {{ ph_datum(doc.wunschtermin) }}</div>{% endif %}
{% if doc.lieferhinweis %}<div class="ph-feld"><b>Lieferhinweis</b> {{ doc.lieferhinweis }}</div>{% endif %}
<table class="ph-tabelle"><thead><tr><th>Pos.</th><th>Bezeichnung</th><th>Ausführung</th><th>Marke</th><th class="zahl">Menge</th></tr></thead><tbody>
{% for p in doc.positionen %}<tr><td>{{ loop.index }}</td><td>{{ p.beschreibung }}{% if p.bereich %} <small>· {{ p.bereich }}</small>{% endif %}{% if p.seriennummer %}<br><small>SN {{ p.seriennummer }}</small>{% endif %}</td><td>{{ p.ausfuehrung_text or "" }}</td><td>{{ p.marke or "" }}</td><td class="zahl">{{ p.menge }}</td></tr>{% endfor %}
</tbody></table>
{% if doc.pakete %}<p class="text-muted">{{ doc.pakete|length }} Paket(e){% if doc.gesamtgewicht_g %}, {{ "%.1f"|format(doc.gesamtgewicht_g / 1000) }} kg{% endif %}{% if doc.zerbrechlich %} · zerbrechlich{% endif %}</p>{% endif %}
<p class="ph-hinweis">Bitte prüfen Sie die Ware bei Übergabe auf Vollständigkeit und sichtbare Schäden. Beanstandungen vermerken Sie bitte unten. Ihre gesetzlichen Gewährleistungsrechte bleiben unberührt.</p>
<table style="width:100%;margin-top:14mm"><tr>
<td style="width:50%;vertical-align:bottom;padding-right:8mm"><div style="border-top:1px solid #30373e;padding-top:2mm;font-size:8pt">Ort, Datum</div></td>
<td style="width:50%;vertical-align:bottom"><div style="border-top:1px solid #30373e;padding-top:2mm;font-size:8pt">Unterschrift Empfänger{% if doc.empfaenger_name %} – {{ doc.empfaenger_name }}{% endif %}</div>{% if doc.unterschrift_empfaenger %}<img src="{{ doc.unterschrift_empfaenger }}" style="height:18mm">{% endif %}</td>
</tr></table>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Packliste {{ doc.name }}{% endblock %}
{% block kopfrechts %}Packliste <b>{{ doc.name }}</b><br>{{ ph_datum(doc.datum) }}<br>{{ _(doc.lieferart) }} · {{ _(doc.status) }}{% endblock %}
{% block inhalt %}
<h1>Packliste (intern)</h1>
<div class="ph-feld"><b>Kunde</b> {{ doc.kunde_name or doc.liefer_name or "" }} · {{ doc.liefer_plz or "" }} {{ doc.liefer_ort or "" }} {{ doc.liefer_land or "" }}</div>
<div class="ph-feld"><b>Beleg</b> {{ doc.bestellung or doc.auftrag or "–" }}{% if doc.abholcode %} · Abholcode <b>{{ doc.abholcode }}</b>{% endif %}</div>
{% if doc.lieferhinweis %}<div class="ph-hinweis">{{ doc.lieferhinweis }}</div>{% endif %}
<table class="ph-tabelle"><thead><tr><th style="width:8mm">✓</th><th>Bezeichnung</th><th>EAN / SN</th><th>Paketprofil</th><th class="zahl">Menge</th><th class="zahl">Paket</th></tr></thead><tbody>
{% for p in doc.positionen %}<tr><td style="font-size:14pt">{% if p.gepackt %}☑{% else %}☐{% endif %}</td><td>{{ p.beschreibung }}{% if p.bereich %} <small>· {{ p.bereich }}</small>{% endif %}{% if p.ausfuehrung_text %} · {{ p.ausfuehrung_text }}{% endif %}{% if p.zerbrechlich %} <b style="color:#b91c1c">ZERBRECHLICH</b>{% endif %}{% if p.lagerbestand %}<br><small>Lager: {{ p.lagerbestand }}</small>{% endif %}</td><td>{{ p.ean or "" }}{% if p.seriennummer %} / {{ p.seriennummer }}{% endif %}</td><td>{{ p.paketprofil or "" }}</td><td class="zahl">{{ p.menge_gepackt or 0 }}/{{ p.menge }}</td><td class="zahl">{{ p.paket_nr or "" }}</td></tr>{% endfor %}
</tbody></table>
{% if doc.pakete %}<h2>Pakete</h2><table class="ph-tabelle"><thead><tr><th>#</th><th>Profil</th><th>L × B × H (cm)</th><th class="zahl">Gewicht</th><th>Inhalt</th><th>Sendung</th></tr></thead><tbody>
{% for pk in doc.pakete %}<tr><td>{{ pk.paket_nr }}</td><td>{{ pk.paketprofil or "" }}</td><td>{{ pk.laenge_cm or "?" }} × {{ pk.breite_cm or "?" }} × {{ pk.hoehe_cm or "?" }}</td><td class="zahl">{{ pk.gewicht_g or 0 }} g</td><td>{{ pk.inhalt or "" }}{% if pk.zerbrechlich %} ⚠{% endif %}</td><td>{{ pk.sendung or "" }}</td></tr>{% endfor %}
</tbody></table>{% endif %}
<div class="ph-feld"><b>Versicherung</b> {% if doc.versichern %}ja, {{ ph_betrag(doc.versicherungswert_cent) }}{% else %}nein{% endif %} · <b>Warenwert</b> {{ ph_betrag(doc.warenwert_cent) }}</div>
<div class="ph-feld"><b>Gepackt</b> {{ doc.gepackt_von or "–" }} {{ ph_datum(doc.gepackt_am) }}</div>
<p class="ph-hinweis">Interner Ausdruck – nicht dem Paket beilegen.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Retourenschein {{ doc.name }}{% endblock %}
{% block kopfrechts %}Retourenschein <b>{{ doc.name }}</b><br>{{ ph_datum(doc.creation) }}{% if doc.bestellung %}<br>Bestellung {{ doc.bestellung }}{% endif %}{% endblock %}
{% block inhalt %}
<h1>Retourenschein</h1>
<p>Bitte legen Sie diesen Schein der Rücksendung bei und kleben Sie das Retourenetikett gut sichtbar auf das Paket.</p>
<div class="ph-feld"><b>Rücksendung an</b> {{ doc.empf_firma or doc.empf_name }}<br>{{ doc.empf_strasse }} {{ doc.empf_hausnr }}<br>{{ doc.empf_plz }} {{ doc.empf_ort }}, {{ doc.empf_land }}</div>
<div class="ph-feld"><b>Dienst</b> {{ doc.carrier or "" }} {{ doc.service_name or "" }}{% if doc.tracking_nr %} · Tracking {{ doc.tracking_nr }}{% endif %}</div>
{% if doc.retoure %}<div class="ph-feld"><b>Retoure</b> {{ doc.retoure }}</div>{% endif %}
{% set ls = frappe.get_doc("PH Lieferschein", doc.lieferschein) if doc.lieferschein else None %}
{% if ls %}<table class="ph-tabelle"><thead><tr><th style="width:8mm">Zurück</th><th>Artikel</th><th class="zahl">Menge</th><th>Grund (bitte ankreuzen/ergänzen)</th></tr></thead><tbody>
{% for p in ls.positionen %}<tr><td style="font-size:14pt">☐</td><td>{{ p.beschreibung }}{% if p.ausfuehrung_text %} · {{ p.ausfuehrung_text }}{% endif %}</td><td class="zahl">{{ p.menge }}</td><td>☐ gefällt nicht ☐ beschädigt ☐ falsch ☐ ________</td></tr>{% endfor %}
</tbody></table>{% endif %}
<p class="ph-hinweis">Widerruf nach § 11 FAGG: Die Rücksendefrist beträgt 14 Tage ab Erklärung des Widerrufs. Verpacken Sie zerbrechliche Ware bitte bruchsicher (Originalverpackung). Nach Eingang und Prüfung erstatten wir binnen 14 Tagen auf dem ursprünglichen Zahlungsweg.</p>
<table style="width:100%;margin-top:12mm"><tr><td style="width:50%;padding-right:8mm"><div style="border-top:1px solid #30373e;padding-top:2mm;font-size:8pt">Name</div></td><td><div style="border-top:1px solid #30373e;padding-top:2mm;font-size:8pt">Datum, Unterschrift</div></td></tr></table>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Tourenblatt {{ doc.name }}{% endblock %}
{% block kopfrechts %}Tourenblatt <b>{{ doc.name }}</b><br>{{ ph_datum(doc.datum) }} · {{ _(doc.status) }}{% endblock %}
{% block inhalt %}
<h1>Tourenblatt {{ doc.region or "" }}</h1>
<div class="ph-feld"><b>Fahrzeug</b> {{ doc.fahrzeug or "–" }} · <b>Fahrer</b> {{ frappe.db.get_value("User", doc.fahrer, "full_name") if doc.fahrer else "–" }}{% if doc.team %} · <b>Team</b> {% for t in doc.team %}{{ frappe.db.get_value("User", t.user, "full_name") }} ({{ t.rolle }}){% if not loop.last %}, {% endif %}{% endfor %}{% endif %}</div>
<div class="ph-feld"><b>Abfahrt</b> {{ doc.start_zeit or "" }} · <b>km Start</b> {{ doc.km_start or "______" }} · <b>km Ende</b> {{ doc.km_ende or "______" }}</div>
<table class="ph-tabelle"><thead><tr><th>#</th><th>Art</th><th>Kunde / Adresse</th><th>Zeitfenster</th><th>Unterlagen</th><th>Erledigt / Unterschrift</th></tr></thead><tbody>
{% for s in doc.stopps %}<tr>
<td style="font-size:12pt;font-weight:600">{{ s.reihenfolge }}</td><td>{{ _(s.art) }}</td>
<td><b>{{ s.kunde_name or "" }}</b><br>{{ (s.adresse or "")|replace("\n", ", ") }}<br>{{ s.plz or "" }} {{ s.ort or "" }}{% if s.telefon %}<br>☎ {{ s.telefon }}{% endif %}{% if s.notiz %}<br><small>{{ s.notiz }}</small>{% endif %}</td>
<td>{{ s.zeitfenster_von or "" }}{% if s.zeitfenster_bis %}–{{ s.zeitfenster_bis }}{% endif %}<br><small>{{ s.dauer_min or "" }} min</small></td>
<td>{{ s.lieferschein or s.montage_referenz or "" }}{% if s.lieferschein %}{% for p in frappe.get_all("PH Lieferschein Position", {"parent": s.lieferschein}, ["beschreibung", "menge"]) %}<br><small>{{ p.menge }}× {{ p.beschreibung }}</small>{% endfor %}{% endif %}</td>
<td style="min-width:40mm">☐ {{ _(s.status) }}<br><br><div style="border-top:1px solid #d9d4cc"></div></td>
</tr>{% endfor %}
</tbody></table>
<p class="ph-hinweis">Fotos vorher/nachher und Kundenunterschrift bitte über „Tour heute“ (mobil) erfassen. Dieses Blatt ist der Papier-Rückfall.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Zählliste {{ doc.name }}{% endblock %}
{% block kopfrechts %}Inventur <b>{{ doc.name }}</b><br>Stichtag {{ ph_datum(doc.datum) }}<br>{{ doc.lagerort }}{% endblock %}
{% block inhalt %}
<h1>Zählliste {{ doc.lagerort }}</h1>
<div class="ph-feld"><b>Gezählt von</b> ____________________ · <b>Datum</b> ____________</div>
<table class="ph-tabelle"><thead><tr><th>Platz</th><th>Bestand</th><th>Artikel</th><th>Seriennummer</th><th class="zahl">Soll</th><th class="zahl" style="width:22mm">Ist</th><th>Bemerkung</th></tr></thead><tbody>
{% for p in doc.positionen %}<tr><td>{{ p.platz or "" }}</td><td><small>{{ p.lagerbestand }}</small></td><td>{{ p.produkt_name }}</td><td>{{ p.seriennummer or "" }}</td><td class="zahl">{{ p.soll }}</td><td class="zahl">{% if p.gezaehlt %}{{ p.ist }}{% else %}&nbsp;{% endif %}</td><td>{{ p.grund or "" }} {{ p.bemerkung or "" }}</td></tr>{% endfor %}
</tbody></table>
<div class="ph-feld"><b>Positionen</b> {{ doc.anzahl_positionen }} · <b>Gezählt</b> {{ doc.anzahl_gezaehlt }} · <b>Differenzen</b> {{ doc.differenz_positionen }} ({{ doc.differenz_summe }} Stück)</div>
<p class="ph-hinweis">Zähl-Hinweis: Ausstellungsstücke je Seriennummer einzeln, Accessoires als Stückzahl. Freigabe und Buchung der Differenzen nur durch die Leitung.</p>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Speditionsauftrag {{ doc.name }}{% endblock %}
{% block kopfrechts %}Speditionsauftrag <b>{{ doc.name }}</b><br>{{ doc.richtung }}<br>{% if doc.spediteur_referenz %}Ihre Nr. {{ doc.spediteur_referenz }}<br>{% endif %}{{ ph_datum(doc.creation) }}{% endblock %}
{% block inhalt %}
<h1>Speditionsauftrag</h1>
<p>An: <b>{{ doc.spediteur or "" }}</b>{% if doc.spediteur_email %} · {{ doc.spediteur_email }}{% endif %}</p>
<table class="ph-tabelle"><thead><tr><th style="width:50%">Abholung</th><th>Zustellung</th></tr></thead><tbody><tr>
<td>{{ doc.abhol_name or "" }}<br>{{ doc.abhol_strasse or "" }}<br>{{ doc.abhol_land or "" }}-{{ doc.abhol_plz or "" }} {{ doc.abhol_ort or "" }}{% if doc.abhol_ansprechpartner %}<br>Kontakt: {{ doc.abhol_ansprechpartner }}{% endif %}{% if doc.abhol_telefon %}<br>Tel. {{ doc.abhol_telefon }}{% endif %}<br><b>{{ ph_datum(doc.abhol_datum) if doc.abhol_datum else "nach Vereinbarung" }}</b>{% if doc.abhol_von %} {{ doc.abhol_von }}–{{ doc.abhol_bis or "" }} Uhr{% endif %}</td>
<td>{{ doc.ziel_name or "" }}<br>{{ doc.ziel_strasse or "" }}<br>{{ doc.ziel_land or "" }}-{{ doc.ziel_plz or "" }} {{ doc.ziel_ort or "" }}{% if doc.ziel_ansprechpartner %}<br>Kontakt: {{ doc.ziel_ansprechpartner }}{% endif %}{% if doc.ziel_telefon %}<br>Tel. {{ doc.ziel_telefon }}{% endif %}<br><b>{{ ph_datum(doc.zustell_datum) if doc.zustell_datum else "nach Vereinbarung" }}</b>{% if doc.zustell_von %} {{ doc.zustell_von }}–{{ doc.zustell_bis or "" }} Uhr{% endif %}</td>
</tr></tbody></table>
<h2>Packstücke</h2>
<table class="ph-tabelle"><thead><tr><th>Art</th><th class="zahl">Anz.</th><th>Inhalt</th><th class="zahl">L×B×H cm</th><th class="zahl">kg/Stk.</th><th>Hinweis</th></tr></thead><tbody>
{% for p in doc.packstuecke %}<tr><td>{{ p.art }}</td><td class="zahl">{{ p.anzahl }}</td><td>{{ p.bezeichnung or "" }}</td><td class="zahl">{{ p.laenge_cm or "–" }}×{{ p.breite_cm or "–" }}×{{ p.hoehe_cm or "–" }}</td><td class="zahl">{{ "%.1f"|format((p.gewicht_g or 0)/1000) }}</td><td>{% if p.stapelbar %}stapelbar {% endif %}{% if p.zerbrechlich %}<b>zerbrechlich</b>{% endif %}</td></tr>{% endfor %}
</tbody></table>
<div class="ph-feld"><b>Gesamt</b> {{ doc.anzahl_packstuecke }} Packstücke · {{ "%.1f"|format((doc.gewicht_g or 0)/1000) }} kg · {{ doc.volumen_m3 or 0 }} m³ · {{ doc.lademeter or 0 }} Lademeter (Planwerte){% if doc.versichern %} · Versicherung gewünscht{% endif %}</div>
<h2>Leistungen</h2>
<ul>{% if doc.zustellart %}<li>Zustellung: {{ doc.zustellart }}</li>{% endif %}{% if doc.avis_noetig %}<li>Telefonisches Avis vor Zustellung</li>{% endif %}{% if doc.etage %}<li>Etage {{ doc.etage }}{% if doc.aufzug %} mit Aufzug{% else %} ohne Aufzug{% endif %}</li>{% endif %}{% if doc.hebebuehne %}<li>Hebebühne</li>{% endif %}{% if doc.trageservice %}<li>Trageservice (2 Personen)</li>{% endif %}{% if doc.montage %}<li>Montage</li>{% endif %}{% if doc.verpackung_entsorgen %}<li>Verpackung mitnehmen</li>{% endif %}</ul>
{% if doc.hinweise %}<p><b>Hinweise:</b> {{ doc.hinweise }}</p>{% endif %}
<p>Referenz: {{ doc.lieferschein or doc.herstellerbestellung or "" }}{% if doc.kommission %} · Kommission {{ doc.kommission }}{% endif %}</p>
<p class="ph-hinweis">Bitte bestätigen Sie Termin und Preis schriftlich mit Ihrer Auftragsnummer. Schäden sind auf dem Frachtbrief zu vermerken und uns sofort mit Fotos zu melden.</p>
<table class="ph-tabelle" style="margin-top:12mm"><tr><td style="height:18mm;width:50%">Übernommen (Datum, Unterschrift Fahrer)</td><td>Zugestellt (Datum, Name, Unterschrift){% if doc.unterschrift %}<br><img src="{{ doc.unterschrift }}" style="max-height:16mm"> {{ doc.empfaenger_name or "" }}{% endif %}</td></tr></table>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Warenrücknahme {{ doc.name }}{% endblock %}
{% block kopfrechts %}Warenrücknahme <b>{{ doc.name }}</b><br>{{ doc.anlass }}<br>{% if doc.lieferschein %}Lieferschein {{ doc.lieferschein }}<br>{% endif %}{{ ph_datum(doc.eingegangen_am or doc.creation) }}{% endblock %}
{% block inhalt %}
<h1>Rücknahmeprotokoll</h1>
<p>Kunde: <b>{{ doc.kunde_name or "" }}</b>{% if doc.projekt %} · Projekt {{ doc.projekt }}{% endif %}</p>
{% if doc.grund %}<p>Grund: {{ doc.grund }}</p>{% endif %}
<table class="ph-tabelle"><thead><tr><th>Artikel</th><th>Ausführung</th><th>SN</th><th class="zahl">Menge</th><th>Zustand</th><th>Entscheidung</th></tr></thead><tbody>
{% for p in doc.positionen %}<tr><td>{{ p.beschreibung }}</td><td>{{ p.ausfuehrung_text or "" }}</td><td>{{ p.seriennummer or "" }}</td><td class="zahl">{{ p.menge }}</td><td>{{ p.zustand or "–" }}</td><td>{{ p.entscheidung or "offen" }}</td></tr>{% endfor %}
</tbody></table>
<p class="ph-hinweis">Die Rücknahme bestätigt den Empfang der Ware. Über eine Gutschrift oder Wertminderung entscheidet Platzhirsch nach Prüfung; sie wird gesondert mitgeteilt.</p>
<table class="ph-tabelle" style="margin-top:10mm"><tr><td style="height:18mm;width:50%">Übergeben (Kunde){% if doc.unterschrift_kunde %}<br><img src="{{ doc.unterschrift_kunde }}" style="max-height:16mm"> {{ doc.unterschrift_name or "" }}{% endif %}</td><td>Übernommen (Platzhirsch)</td></tr></table>
{% endblock %}

{% extends "templates/print/ph_basis.html" %}
{% block titel %}Inventurbewertung {{ doc.name }}{% endblock %}
{% block kopfrechts %}Inventurbewertung <b>{{ doc.name }}</b><br>Stichtag {{ ph_datum(doc.stichtag) }}<br>{{ doc.lagerort or "Alle Lagerorte" }}<br>Status: {{ doc.status }}{% endblock %}
{% block inhalt %}
<h1>Inventurbewertung zum {{ ph_datum(doc.stichtag) }}</h1>
<p>Bewertungsmethode: <b>{{ doc.methode }}</b>. {{ doc.methode_beschreibung or "" }}</p>
{% if doc.abwertung_platzhalter %}<p class="ph-hinweis"><b>Hinweis:</b> Die Abwertungssätze sind Platzhalter und vom Steuerberater zu bestätigen.</p>{% endif %}
{% if doc.abwertung_regeln %}<p style="font-size:8.5pt">Abwertungsstaffel: {{ (doc.abwertung_regeln or "").replace("\n", " · ") }}</p>{% endif %}
<table class="ph-tabelle" style="margin:4mm 0"><tr><td>Wert zu Anschaffungskosten</td><td class="zahl">{{ ph_betrag(doc.wert_ak_cent) }}</td><td>Abwertung</td><td class="zahl">{{ ph_betrag(doc.abwertung_cent) }}</td><td><b>Bilanzwert</b></td><td class="zahl"><b>{{ ph_betrag(doc.wert_cent) }}</b></td></tr>
<tr><td>Positionen</td><td class="zahl">{{ doc.anzahl_positionen or 0 }}</td><td>Stück</td><td class="zahl">{{ doc.menge_gesamt or 0 }}</td><td>ohne EK</td><td class="zahl">{{ doc.ohne_ek or 0 }}</td></tr></table>
{% for schluessel, titel in [("lagerort", "Lagerort"), ("warengruppe", "Warengruppe"), ("marke", "Marke")] %}
<h3>Summen je {{ titel }}</h3>
<table class="ph-tabelle"><thead><tr><th>{{ titel }}</th><th class="zahl">Pos.</th><th class="zahl">Stück</th><th class="zahl">Wert AK</th><th class="zahl">Abwertung</th><th class="zahl">Bilanzwert</th></tr></thead><tbody>
{% for g in doc.positionen|groupby(schluessel) %}<tr><td>{{ g.grouper or "–" }}</td><td class="zahl">{{ g.list|length }}</td><td class="zahl">{{ g.list|sum(attribute="menge") }}</td><td class="zahl">{{ ph_betrag(g.list|sum(attribute="wert_ak_cent")) }}</td><td class="zahl">{{ ph_betrag(g.list|sum(attribute="abwertung_cent")) }}</td><td class="zahl">{{ ph_betrag(g.list|sum(attribute="wert_cent")) }}</td></tr>{% endfor %}
</tbody></table>
{% endfor %}
<h3>Positionen</h3>
<table class="ph-tabelle" style="font-size:8pt"><thead><tr><th>Lagerort/Platz</th><th>Artikel</th><th>Art</th><th class="zahl">Menge</th><th class="zahl">Einstandspreis</th><th>EK-Quelle</th><th class="zahl">Abw. %</th><th class="zahl">Einzelwert</th><th class="zahl">Bilanzwert</th><th>Hinweis</th></tr></thead><tbody>
{% for p in doc.positionen %}<tr><td>{{ p.lagerort }}{% if p.platz %} / {{ p.platz }}{% endif %}</td><td>{{ p.produkt_name or p.produkt }}{% if p.seriennummer %} (SN {{ p.seriennummer }}){% endif %}</td><td>{{ p.bewertungsart }}</td><td class="zahl">{{ p.menge }}</td><td class="zahl">{{ ph_betrag(p.einstandspreis_cent) }}</td><td>{{ p.ek_quelle or "" }}</td><td class="zahl">{{ "%.1f"|format((p.abwertung_promille or 0) / 10) }}</td><td class="zahl">{{ ph_betrag(p.einzelwert_cent) }}</td><td class="zahl">{{ ph_betrag(p.wert_cent) }}</td><td>{{ p.hinweis or "" }}</td></tr>{% endfor %}
</tbody></table>
{% if doc.buchungsvorschlag %}<p><b>Buchungsvorschlag Bestandsveränderung:</b> {{ doc.buchungsvorschlag }}{% if doc.vorherige_bewertung %} (Vergleich {{ doc.vorherige_bewertung }}: {{ ph_betrag(doc.wert_vorher_cent) }}){% endif %}</p>{% endif %}
{% if doc.hinweise %}<p class="ph-hinweis">{{ (doc.hinweise or "").replace("\n", "<br>") }}</p>{% endif %}
<p>Die Bestandsaufnahme wurde vollständig und nach bestem Wissen durchgeführt; Mengen laut Bewegungsjournal zum Stichtag, Bewertung nach der angegebenen Methode.</p>
